#[test]
fn parser_accepts_asymmetric_property_visibility_metadata() {
    let program = parser::parse(
        "<?php
class Book {
    public private(set) string $title = \"ptn\";
    protected private(set) int $year;
    protected(set) array $tags;
    public protected(set) static int $reads = 0;
}
",
    )
    .unwrap();

    assert_eq!(
        program.classes[0].properties[0].visibility,
        PropertyVisibility::Public
    );
    assert_eq!(
        program.classes[0].properties[0].set_visibility,
        PropertyVisibility::Private
    );
    assert_eq!(
        program.classes[0].properties[1].visibility,
        PropertyVisibility::Protected
    );
    assert_eq!(
        program.classes[0].properties[1].set_visibility,
        PropertyVisibility::Private
    );
    assert_eq!(
        program.classes[0].properties[2].visibility,
        PropertyVisibility::Public
    );
    assert_eq!(
        program.classes[0].properties[2].set_visibility,
        PropertyVisibility::Protected
    );
    assert_eq!(
        program.classes[0].static_properties[0].visibility,
        PropertyVisibility::Public
    );
    assert_eq!(
        program.classes[0].static_properties[0].set_visibility,
        PropertyVisibility::Protected
    );
}

#[test]
fn parser_accepts_property_hook_prototype_metadata() {
    let program = parser::parse(
        "<?php
class ParentBook {
    public mixed $title { get => 'fallback'; }
}
class Book extends ParentBook {
    public protected(set) mixed $title = 'ptn';
}
",
    )
    .unwrap();

    assert!(program.classes[0].properties[0].has_hooks);
    assert!(matches!(
        program.classes[0].properties[0].hook_get_value.as_ref(),
        Some(Expr::String(value, _)) if value == "fallback"
    ));
    assert_eq!(program.classes[1].properties[0].name, "title");
    assert_eq!(
        program.classes[1].properties[0].set_visibility,
        PropertyVisibility::Protected
    );
}

#[test]
fn parser_lowers_asymmetric_constructor_promoted_properties() {
    let program = parser::parse(
        "<?php
class Book {
    public function __construct(
        public private(set) string $title,
        protected(set) int $year,
    ) {}
}
",
    )
    .unwrap();

    assert_eq!(program.classes[0].properties.len(), 2);
    assert_eq!(program.classes[0].properties[0].name, "title");
    assert_eq!(
        program.classes[0].properties[0].visibility,
        PropertyVisibility::Public
    );
    assert_eq!(
        program.classes[0].properties[0].set_visibility,
        PropertyVisibility::Private
    );
    assert_eq!(program.classes[0].properties[1].name, "year");
    assert_eq!(
        program.classes[0].properties[1].visibility,
        PropertyVisibility::Public
    );
    assert_eq!(
        program.classes[0].properties[1].set_visibility,
        PropertyVisibility::Protected
    );

    let constructor = &program.classes[0].methods[0];
    assert_eq!(constructor.body.len(), 2);
    assert!(matches!(
        &constructor.body[0],
        Statement::Expression {
            expression: Expr::Assign {
                target: AssignmentTarget::Property { name, .. },
                value,
                ..
            },
            ..
        } if name == "title" && matches!(value.as_ref(), Expr::Variable(variable, _) if variable == "title")
    ));
}

