#[test]
fn parser_accepts_override_attributes_with_matching_contracts() {
    let program = parser::parse(
        "<?php
interface Contract {
    public mixed $contract { get; }
    public mixed $promoted { get; }
    public function run();
}

trait RequiredByTrait {
    abstract public function traitRun();
}

class Base {
    protected mixed $base;
    public static mixed $shared;
    protected function parentRun() {}
}

class Child extends Base implements Contract {
    use RequiredByTrait;

    #[\\Override]
    public mixed $contract;

    #[\\Override]
    public mixed $base;

    #[\\Override]
    public static mixed $shared;

    #[\\Override]
    public function run() {}

    #[\\Override]
    public function parentRun() {}

    #[\\Override]
    public function traitRun() {}

    public function __construct(
        #[\\Override]
        public mixed $promoted,
    ) {}
}
",
    )
    .unwrap();

    let child = program
        .classes
        .iter()
        .find(|class| class.name == "Child")
        .unwrap();
    assert!(child
        .properties
        .iter()
        .any(|property| property.name == "contract" && property.has_override_attribute));
    assert!(child
        .properties
        .iter()
        .any(|property| property.name == "base" && property.has_override_attribute));
    assert!(child
        .properties
        .iter()
        .any(|property| property.name == "promoted" && property.has_override_attribute));
    assert!(child
        .static_properties
        .iter()
        .any(|property| property.name == "shared" && property.has_override_attribute));
    assert!(child
        .methods
        .iter()
        .any(|method| method.name == "run" && method.has_override_attribute));
    assert!(child
        .methods
        .iter()
        .any(|method| method.name == "parentRun" && method.has_override_attribute));
    assert!(child
        .methods
        .iter()
        .any(|method| method.name == "traitRun" && method.has_override_attribute));
}

#[test]
fn parser_preserves_modeled_builtin_attribute_metadata() {
    let source = "<?php
#[\\Deprecated(\"use newer\") ]
function old_fn() {}

#[\\Deprecated(since: \"1.0\", message: \"use newest\") ]
function older_fn() {}

#[\\Deprecated(\"use oldest\", \"0.9\") ]
function oldest_fn() {}

#[\\NoDiscard(\"check it\") ]
function important(): int { return 1; }

#[\\AllowDynamicProperties]
class Bag {}
";
    let program = parser::parse(source).unwrap();

    assert_eq!(
        program.functions[0]
            .attributes
            .deprecated_message
            .as_deref(),
        Some("use newer")
    );
    assert_eq!(
        program.functions[1]
            .attributes
            .deprecated_message
            .as_deref(),
        Some("use newest")
    );
    assert_eq!(
        program.functions[1].attributes.deprecated_since.as_deref(),
        Some("1.0")
    );
    assert_eq!(
        program.functions[2]
            .attributes
            .deprecated_message
            .as_deref(),
        Some("use oldest")
    );
    assert_eq!(
        program.functions[2].attributes.deprecated_since.as_deref(),
        Some("0.9")
    );
    assert_eq!(
        program.functions[3]
            .attributes
            .no_discard_message
            .as_deref(),
        Some("check it")
    );
    assert!(program.classes[0].attributes.has_allow_dynamic_properties);
}

#[test]
fn parser_validates_attribute_argument_surface() {
    let variable_name = parser::parse("<?php #[$x] class A {}").unwrap_err();
    assert_eq!(variable_name.kind, DiagnosticKind::ParseError);
    assert_eq!(
        variable_name.message,
        "syntax error, unexpected variable \"$x\""
    );

    let call_argument = parser::parse("<?php #[A(foo())] class C {}").unwrap_err();
    assert_eq!(call_argument.kind, DiagnosticKind::Fatal);
    assert_eq!(
        call_argument.message,
        "Constant expression contains invalid operations"
    );

    let dynamic_class_constant = parser::parse("<?php #[A(a->b::c)] class C {}").unwrap_err();
    assert_eq!(dynamic_class_constant.kind, DiagnosticKind::Fatal);
    assert_eq!(
        dynamic_class_constant.message,
        "Dynamic class names are not allowed in compile-time class constant references"
    );

    let empty_array_element = parser::parse("<?php #[A([,]->e)] class C {}").unwrap_err();
    assert_eq!(empty_array_element.kind, DiagnosticKind::Fatal);
    assert_eq!(
        empty_array_element.message,
        "Cannot use empty array elements in arrays"
    );

    let unpack_argument = parser::parse("<?php #[A(...[1])] class C {}").unwrap_err();
    assert_eq!(unpack_argument.kind, DiagnosticKind::Fatal);
    assert_eq!(
        unpack_argument.message,
        "Cannot use unpacking in attribute argument list"
    );

    let program = parser::parse(
        "<?php
#[\\Deprecated(message: 1234)]
function old_fn() {}

#[\\NoDiscard(1234)]
function important(): int { return 1; }
",
    )
    .unwrap();
    assert_eq!(
        program.functions[0]
            .attributes
            .deprecated_message
            .as_deref(),
        Some("1234")
    );
    assert_eq!(
        program.functions[1]
            .attributes
            .no_discard_message
            .as_deref(),
        Some("1234")
    );

    let strict_deprecated = parser::parse(
        "<?php declare(strict_types=1);
#[\\Deprecated(1234)]
function old_fn() {}
",
    )
    .unwrap_err();
    assert_eq!(strict_deprecated.kind, DiagnosticKind::Fatal);
    assert_eq!(
        strict_deprecated.message,
        "Deprecated::__construct(): Argument #1 ($message) must be of type ?string, int given"
    );
    let strict_deprecated_uncaught = strict_deprecated.uncaught.unwrap();
    assert_eq!(strict_deprecated_uncaught.throwable, "TypeError");
    assert_eq!(
        strict_deprecated_uncaught.call_frame.as_deref(),
        Some("Deprecated->__construct(1234)")
    );

    let array_no_discard = parser::parse(
        "<?php
#[\\NoDiscard([])]
function important(): int { return 1; }
",
    )
    .unwrap_err();
    assert_eq!(array_no_discard.kind, DiagnosticKind::Fatal);
    assert_eq!(
        array_no_discard.message,
        "NoDiscard::__construct(): Argument #1 ($message) must be of type ?string, array given"
    );
    assert_eq!(
        array_no_discard.uncaught.unwrap().call_frame.as_deref(),
        Some("NoDiscard->__construct(Array)")
    );

    let enum_deprecated = parser::parse(
        "<?php
#[\\Deprecated(\\Random\\IntervalBoundary::ClosedOpen)]
function old_fn() {}
",
    )
    .unwrap_err();
    assert_eq!(enum_deprecated.kind, DiagnosticKind::Fatal);
    assert_eq!(
        enum_deprecated.message,
        "Deprecated::__construct(): Argument #1 ($message) must be of type ?string, Random\\IntervalBoundary given"
    );
    assert_eq!(
        enum_deprecated.uncaught.unwrap().call_frame.as_deref(),
        Some("Deprecated->__construct(Random\\IntervalBoundary::ClosedOpen)")
    );

    let repeated_attribute =
        parser::parse("<?php #[Attribute] #[Attribute] class A {}").unwrap_err();
    assert_eq!(repeated_attribute.kind, DiagnosticKind::Fatal);
    assert_eq!(
        repeated_attribute.message,
        "Attribute \"Attribute\" must not be repeated"
    );

    let parameter_target =
        parser::parse("<?php function demo(#[Deprecated] $value) {}").unwrap_err();
    assert_eq!(parameter_target.kind, DiagnosticKind::Fatal);
    assert_eq!(
        parameter_target.message,
        "Attribute \"Deprecated\" cannot target parameter (allowed targets: class, function, method, class constant, constant)"
    );

    let constant_target = parser::parse("<?php #[Attribute] const EXAMPLE = true;").unwrap_err();
    assert_eq!(constant_target.kind, DiagnosticKind::Fatal);
    assert_eq!(
        constant_target.message,
        "Attribute \"Attribute\" cannot target constant (allowed targets: class)"
    );

    let repeated_const_deprecated =
        parser::parse("<?php #[Deprecated] #[Deprecated] const MY_CONST = true;").unwrap_err();
    assert_eq!(repeated_const_deprecated.kind, DiagnosticKind::Fatal);
    assert_eq!(
        repeated_const_deprecated.message,
        "Attribute \"Deprecated\" must not be repeated"
    );

    let return_type_will_change_function =
        parser::parse("<?php #[ReturnTypeWillChange] function demo() {}").unwrap_err();
    assert_eq!(return_type_will_change_function.kind, DiagnosticKind::Fatal);
    assert_eq!(
        return_type_will_change_function.message,
        "Attribute \"ReturnTypeWillChange\" cannot target function (allowed targets: method)"
    );

    let return_type_will_change_property =
        parser::parse("<?php class Demo { #[ReturnTypeWillChange] public int $value; }")
            .unwrap_err();
    assert_eq!(return_type_will_change_property.kind, DiagnosticKind::Fatal);
    assert_eq!(
        return_type_will_change_property.message,
        "Attribute \"ReturnTypeWillChange\" cannot target property (allowed targets: method)"
    );

    let multiple_constants =
        parser::parse("<?php #[Foo] const First = 1, Second = 2;").unwrap_err();
    assert_eq!(multiple_constants.kind, DiagnosticKind::Fatal);
    assert_eq!(
        multiple_constants.message,
        "Cannot apply attributes to multiple constants at once"
    );

    let delayed_repetition =
        parser::parse("<?php #[DelayedTargetValidation] #[NoDiscard] #[NoDiscard] class Demo {}")
            .unwrap_err();
    assert_eq!(delayed_repetition.kind, DiagnosticKind::Fatal);
    assert_eq!(
        delayed_repetition.message,
        "Attribute \"NoDiscard\" must not be repeated"
    );
}

#[test]
fn compile_attribute_diagnostics_route_through_user_error_handler_to_native_binary() {
    let root = temp_dir("ptn-native-attribute-diagnostics-handler");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("attribute-diagnostics-handler.php");
    let output = root.join("attribute-diagnostics-handler-bin");
    fs::write(
        &input,
        "<?php
set_error_handler(function (int $errno, string $errstr) {
    echo $errno, ':', $errstr, \"\\n\";
    return true;
});

#[\\Deprecated(TEST)]
const TEST = 'from itself';

#[\\Deprecated]
function old_fn(): int { return 1; }

#[\\NoDiscard]
function important(): int { return 2; }

#[\\Deprecated]
trait OldTrait {}

class UsesTrait {
    use OldTrait;
}

TEST;
old_fn();
important();
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "16384:Trait OldTrait used by UsesTrait is deprecated\n",
            "16384:Constant TEST is deprecated, from itself\n",
            "16384:Function old_fn() is deprecated\n",
            "512:The return value of function important() should either be used or intentionally ignored by casting it as (void)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_emit_user_deprecation(&runtime.diagnostics"));
    assert!(c_source.contains("ptn_emit_user_warning(&runtime.diagnostics"));
}

#[test]
fn compile_attribute_throwing_error_handler_remains_installed_to_native_binary() {
    let root = temp_dir("ptn-native-attribute-throwing-handler");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("attribute-throwing-handler.php");
    let output = root.join("attribute-throwing-handler-bin");
    fs::write(
        &input,
        "<?php
set_error_handler(function (int $errno, string $errstr, ?string $errfile = null, ?int $errline = null) {
    throw new ErrorException($errstr, 0, $errno, $errfile, $errline);
});

#[\\Deprecated(TEST)]
const TEST = 'from itself';

#[\\Deprecated]
const TEST2 = 'from another';

#[\\Deprecated(TEST2)]
const TEST3 = 1;

#[\\NoDiscard]
function important(): int { return 1; }

try {
    TEST;
} catch (ErrorException $e) {
    echo 'Caught: ', $e->getMessage(), \"\\n\";
}

try {
    TEST3;
} catch (ErrorException $e) {
    echo 'Caught: ', $e->getMessage(), \"\\n\";
}

try {
    important();
} catch (ErrorException $e) {
    echo 'Caught: ', $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "Caught: Constant TEST is deprecated, from itself\n",
            "Caught: Constant TEST2 is deprecated\n",
            "Caught: The return value of function important() should either be used or intentionally ignored by casting it as (void)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_error_handler_stack_and_trigger_error_to_native_binary() {
    let root = temp_dir("ptn-native-error-handler-stack-trigger");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("error-handler-stack-trigger.php");
    let output = root.join("error-handler-stack-trigger-bin");
    fs::write(
        &input,
        "<?php
set_error_handler(function ($errno, $errstr) {
    echo 'first:', $errno, ':', $errstr, \"\\n\";
    return true;
});
set_error_handler(function ($errno, $errstr) {
    echo 'second:', $errno, ':', $errstr, \"\\n\";
    return true;
});
trigger_error('alpha');
restore_error_handler();
trigger_error('beta');
set_error_handler(null);
trigger_error('gamma');
restore_error_handler();
trigger_error('delta');
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains("second:1024:alpha\n"), "{stdout}");
    assert!(stdout.contains("first:1024:beta\n"), "{stdout}");
    assert!(stdout.contains("Notice: gamma in ptn on line"), "{stdout}");
    assert!(stdout.contains("first:1024:delta\n"), "{stdout}");
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

