#[test]
fn parser_accepts_instance_class_methods_and_object_callables() {
    let program = parser::parse(
        "<?php
class Worker {
    public function run($value) { return $value + 1; }
}
$worker = new Worker();
echo $worker->run(3);
call_user_func([$worker, \"run\"], 4);",
    )
    .unwrap();
    assert_eq!(program.classes.len(), 1);
    assert_eq!(program.classes[0].methods.len(), 1);
    assert_eq!(program.classes[0].methods[0].name, "run");
    assert!(!program.classes[0].methods[0].is_static);
    assert_eq!(program.statements.len(), 3);
    assert!(matches!(
        &program.statements[0],
        Statement::Assign {
            value: Expr::NewObject { class_name, .. },
            ..
        } if class_name == "Worker"
    ));
    assert!(matches!(
        &program.statements[1],
        Statement::Echo { expressions, .. }
            if matches!(&expressions[0], Expr::MethodCall { name, .. } if name == "run")
    ));
    assert!(matches!(
        &program.statements[2],
        Statement::Call { name, arguments, .. }
            if name == "call_user_func" && arguments.len() == 2
    ));
}

#[test]
fn parser_accepts_simple_class_inheritance_metadata() {
    let program = parser::parse(
        "<?php
class Base {
    public function label($value) { return $value; }
}

class Child extends Base {
    public function own($value) { return $this->label($value); }
}",
    )
    .unwrap();

    assert_eq!(program.classes.len(), 2);
    assert_eq!(program.classes[0].name, "Base");
    assert_eq!(program.classes[0].parent_name, None);
    assert_eq!(program.classes[1].name, "Child");
    assert_eq!(program.classes[1].parent_name.as_deref(), Some("Base"));
    assert_eq!(program.classes[1].methods.len(), 1);
}

#[test]
fn parser_accepts_anonymous_class_metadata_and_instanceof() {
    let program = parser::parse(
        "<?php
interface Contract {
    public function run();
}

class Base {
    public function label($value) { return $value; }
}

$worker = new class(\"native\") extends Base implements Contract {
    public $name;

    public function __construct($name) {
        $this->name = $name;
    }

    public function run() {
        return $this->label($this->name);
    }
};

var_dump($worker instanceof Base, $worker instanceof Contract);
",
    )
    .unwrap();

    assert_eq!(program.classes.len(), 3);
    assert_eq!(program.classes[2].name, "Base@anonymous");
    assert_eq!(program.classes[2].parent_name.as_deref(), Some("Base"));
    assert_eq!(program.classes[2].interfaces, vec!["Contract"]);
    assert_eq!(program.classes[2].properties[0].name, "name");
    assert_eq!(program.classes[2].methods.len(), 2);

    let Statement::Assign { value, .. } = &program.statements[0] else {
        panic!("expected anonymous class assignment");
    };
    assert!(matches!(
        value,
        Expr::NewObject { class_name, .. } if class_name == "Base@anonymous"
    ));

    let Statement::Call { arguments, .. } = &program.statements[1] else {
        panic!("expected var_dump statement");
    };
    assert!(matches!(
        &arguments[0],
        Expr::InstanceOf {
            target: InstanceOfTarget::ClassName { name, .. },
            ..
        } if name == "Base"
    ));
    assert!(matches!(
        &arguments[1],
        Expr::InstanceOf {
            target: InstanceOfTarget::ClassName { name, .. },
            ..
        } if name == "Contract"
    ));
}

