    fs::write(
        &input,
        "<?php\n\
$items = [\"a\" => \"A\", \"b\" => \"B\", \"c\" => \"C\"];\n\
foreach ($items as $key => $value) {\n\
    echo $key, \"=\", $value, \"\\n\";\n\
    if ($key === \"a\") {\n\
        unset($items[\"a\"]);\n\
        unset($items[\"b\"]);\n\
        $items[] = \"D\";\n\
    }\n\
    if ($key === \"b\") {\n\
        unset($items[\"c\"]);\n\
    }\n\
}\n\
var_dump($items);",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

