#[test]
fn parser_accepts_runtime_checked_array_cursor_mutation_calls() {
    parser::parse("<?php next([1, 2]);").unwrap();
    parser::parse("<?php var_dump(reset(array(1, 2)));").unwrap();
    parser::parse("<?php $items = [1, 2]; var_dump(prev(current($items)));").unwrap();
    parser::parse("<?php $items = [1, 2]; next(($items));").unwrap();
    parser::parse("<?php $items = [[1], [2]]; end($items[0]);").unwrap();
    parser::parse("<?php function f() { return [1, 2]; } var_dump(next(f()));").unwrap();
    parser::parse("<?php $items = [[1, 2]]; var_dump(prev(current($items)));").unwrap();
}

#[test]
fn parser_rejects_non_variable_array_by_ref_mutation_calls() {
    for (source, function) in [
        ("<?php array_pop([1, 2]);", "array_pop"),
        ("<?php var_dump(array_shift(array(1, 2)));", "array_shift"),
        ("<?php array_push([1], 2);", "array_push"),
        ("<?php array_unshift([1], 2);", "array_unshift"),
        ("<?php arsort([3, 2, 1]);", "arsort"),
        ("<?php asort([3, 2, 1]);", "asort"),
        ("<?php krsort([3 => \"c\", 1 => \"a\"]);", "krsort"),
        ("<?php ksort([3 => \"c\", 1 => \"a\"]);", "ksort"),
        ("<?php natsort([\"img2\", \"img1\"]);", "natsort"),
        ("<?php rsort([3, 2, 1]);", "rsort"),
        ("<?php shuffle([1, 2, 3]);", "shuffle"),
        ("<?php sort([3, 2, 1]);", "sort"),
        ("<?php uasort([3, 2, 1], \"strcmp\");", "uasort"),
        (
            "<?php uksort([3 => \"c\", 1 => \"a\"], \"strcmp\");",
            "uksort",
        ),
        ("<?php usort([3, 2, 1], \"strcmp\");", "usort"),
        ("<?php rsort([3, 2, 1]);", "rsort"),
    ] {
        let error = parser::parse(source).unwrap_err();
        assert!(
            error.message.contains(&format!(
                "{function}() requires a direct variable array argument"
            )),
            "unexpected diagnostic for {function}: {}",
            error.message
        );
        assert!(error
            .message
            .contains("non-variable array mutation targets are unsupported"));
    }

    parser::parse("<?php $items = [1, 2]; array_pop(($items));").unwrap();
    parser::parse("<?php $items = [1]; array_push(($items), 2);").unwrap();
    parser::parse("<?php $items = [[1], [2]]; array_push($items[0], 0);").unwrap();
    parser::parse("<?php $items = [1]; array_unshift(($items), 0);").unwrap();
    parser::parse("<?php $items = [[1], [2]]; var_dump(array_shift(current($items)));").unwrap();
    parser::parse("<?php $items = [\"b\" => 2, \"a\" => 1]; arsort(($items));").unwrap();
    parser::parse("<?php $items = [\"b\" => 2, \"a\" => 1]; asort(($items));").unwrap();
    parser::parse("<?php $items = [2 => \"b\", 1 => \"a\"]; krsort(($items));").unwrap();
    parser::parse("<?php $items = [2 => \"b\", 1 => \"a\"]; ksort(($items));").unwrap();
    parser::parse("<?php $items = [\"img2\", \"img10\", \"img1\"]; natsort(($items));").unwrap();
    parser::parse("<?php $items = [3, 2, 1]; rsort(($items));").unwrap();
    parser::parse("<?php $items = [1, 2]; shuffle(($items));").unwrap();
    parser::parse("<?php $items = [3, 2, 1]; sort(($items));").unwrap();
    parser::parse("<?php $items = [[1], [2]]; array_pop($items[0]);").unwrap();
    parser::parse("<?php $items = [[1], [2]]; array_shift($items[0]);").unwrap();
    parser::parse("<?php $items = [[1], [2]]; array_push($items[0], 3);").unwrap();
    parser::parse("<?php $items = [[1], [2]]; array_unshift($items[0], 0);").unwrap();
    parser::parse("<?php $items = [[1], [2]]; var_dump(array_shift(current($items)));").unwrap();
    parser::parse(
        "<?php $stack = [[[1]]]; var_dump(array_shift(array_shift(array_shift($stack))));",
    )
    .unwrap();
}

#[test]
fn parser_accepts_sort_flags_and_rejects_unsupported_sort_family_mutation_targets() {
    for source in [
        "<?php $items = [3, 2, 1]; sort($items, SORT_REGULAR);",
        "<?php $items = [3, 2, 1]; sort($items, SORT_STRING);",
        "<?php $items = [3, 2, 1]; sort($items, SORT_STRING | SORT_FLAG_CASE);",
        "<?php $items = [3, 2, 1]; sort($items, SORT_NATURAL);",
        "<?php $items = [3, 2, 1]; arsort($items, SORT_REGULAR);",
        "<?php $items = [3, 2, 1]; arsort($items, SORT_STRING);",
        "<?php $items = [3, 2, 1]; asort($items, SORT_REGULAR);",
        "<?php $items = [3, 2, 1]; asort($items, SORT_NUMERIC);",
        "<?php $items = [3, 2, 1]; ksort($items, SORT_REGULAR);",
        "<?php $items = [3, 2, 1]; ksort($items, SORT_NATURAL | SORT_FLAG_CASE);",
        "<?php $items = [3, 2, 1]; krsort($items, SORT_REGULAR);",
        "<?php $items = [3, 2, 1]; krsort($items, SORT_STRING);",
        "<?php $items = [3, 2, 1]; rsort($items, SORT_REGULAR);",
        "<?php $items = [3, 2, 1]; rsort($items, SORT_NUMERIC);",
        "<?php $items = [3, 2, 1]; sort($items, 0);",
        "<?php $items = [3, 2, 1]; sort($items, (SORT_REGULAR));",
        "<?php $items = [3, 2, 1]; sort($items, 999);",
        "<?php $items = [[3, 2, 1]]; asort($items[0]);",
        "<?php $items = [[3, 2, 1]]; sort($items[0], SORT_REGULAR);",
        "<?php $items = [[\"img2\", \"img1\"]]; natsort($items[0]);",
        "<?php $items = [[3, 2, 1]]; usort($items[0], \"cmp\");",
        "<?php $items = [[3 => \"c\", 1 => \"a\"]]; uksort($items[0], \"cmp\");",
    ] {
        parser::parse(source).unwrap();
    }

    for (source, function, target_message) in [
        (
            "<?php sort([3, 2, 1], SORT_REGULAR);",
            "sort",
            "non-variable array mutation targets are unsupported",
        ),
        (
            "<?php $items = [\"img2\", \"img1\"]; natsort($items, SORT_REGULAR);",
            "natsort",
            "extra arguments are unsupported",
        ),
        (
            "<?php $items = [\"img2\", \"img1\"]; natcasesort($items, SORT_REGULAR);",
            "natcasesort",
            "extra arguments are unsupported",
        ),
    ] {
        let error = parser::parse(source).unwrap_err();
        assert!(
            error.message.contains(&format!("{function}()")),
            "unexpected diagnostic for {function}: {}",
            error.message
        );
        assert!(
            error.message.contains(target_message),
            "unexpected diagnostic for {function}: {}",
            error.message
        );
    }

    parser::parse("<?php $items = [3, 2, 1]; array_multisort($items);").unwrap();
    parser::parse("<?php array_multisort([1, 3, 2]);").unwrap();
    parser::parse("<?php array_multisort([]);").unwrap();
    parser::parse(
        "<?php $left = [2, 1]; $right = [\"b\", \"a\"]; array_multisort($left, SORT_ASC, SORT_REGULAR, $right, SORT_DESC, SORT_STRING);",
    )
    .unwrap();
    parser::parse("<?php $items = [3, 2, 1]; usort($items, \"cmp\");").unwrap();
    parser::parse("<?php $items = [3, 2, 1]; uasort($items, \"cmp\");").unwrap();
    parser::parse("<?php $items = [3 => \"c\", 1 => \"a\"]; uksort($items, \"cmp\");").unwrap();
}

#[test]
fn compile_array_multisort_to_native_binary() {
    let root = temp_dir("ptn-native-array-multisort");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-multisort.php");
    let output = root.join("array-multisort-bin");
    fs::write(
        &input,
        "<?php\n\
$ar1 = [\"row1\" => 2, \"row2\" => 1, \"row3\" => 1];\n\
$ar2 = [\"row1\" => 2, \"row2\" => \"aa\", \"row3\" => \"1\"];\n\
var_dump(array_multisort($ar1, SORT_ASC, SORT_REGULAR, $ar2, SORT_DESC, SORT_STRING));\n\
var_dump($ar1, $ar2);\n\
$labels = [\"Second\", \"First.1\", \"First.2\", \"First.3\", \"Twentieth\", \"Tenth\", \"Third\"];\n\
$strings = [\"2 a\", \"1 bb 1\", \"1 bB 2\", \"1 BB 3\", \"20 c\", \"10 d\", \"3 e\"];\n\
array_multisort($strings, SORT_STRING | SORT_FLAG_CASE, $labels);\n\
var_dump($labels, $strings);\n\
$copy = [3, 2, 1];\n\
$alias = $copy;\n\
array_multisort($copy);\n\
var_dump($copy, $alias);\n\
var_dump(array_multisort([1, 3, 2, 4]));\n\
var_dump(array_multisort([]));\n\
try { $a = [1]; array_multisort($a, SORT_ASC, SORT_ASC); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }\n\
try { $a = [1, 2]; $b = [1]; array_multisort($a, $b); } catch (ValueError $e) { echo $e->getMessage(), \"\\n\"; }\n\
var_dump(function_exists(\"array_multisort\"));",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "array(3) {\n",
            "  [\"row2\"]=>\n",
            "  int(1)\n",
            "  [\"row3\"]=>\n",
            "  int(1)\n",
            "  [\"row1\"]=>\n",
            "  int(2)\n",
            "}\n",
            "array(3) {\n",
            "  [\"row2\"]=>\n",
            "  string(2) \"aa\"\n",
            "  [\"row3\"]=>\n",
            "  string(1) \"1\"\n",
            "  [\"row1\"]=>\n",
            "  int(2)\n",
            "}\n",
            "array(7) {\n",
            "  [0]=>\n",
            "  string(7) \"First.1\"\n",
            "  [1]=>\n",
            "  string(7) \"First.2\"\n",
            "  [2]=>\n",
            "  string(7) \"First.3\"\n",
            "  [3]=>\n",
            "  string(5) \"Tenth\"\n",
            "  [4]=>\n",
            "  string(6) \"Second\"\n",
            "  [5]=>\n",
            "  string(9) \"Twentieth\"\n",
            "  [6]=>\n",
            "  string(5) \"Third\"\n",
            "}\n",
            "array(7) {\n",
            "  [0]=>\n",
            "  string(6) \"1 bb 1\"\n",
            "  [1]=>\n",
            "  string(6) \"1 bB 2\"\n",
            "  [2]=>\n",
            "  string(6) \"1 BB 3\"\n",
            "  [3]=>\n",
            "  string(4) \"10 d\"\n",
            "  [4]=>\n",
            "  string(3) \"2 a\"\n",
            "  [5]=>\n",
            "  string(4) \"20 c\"\n",
            "  [6]=>\n",
            "  string(3) \"3 e\"\n",
            "}\n",
            "array(3) {\n",
            "  [0]=>\n",
            "  int(1)\n",
            "  [1]=>\n",
            "  int(2)\n",
            "  [2]=>\n",
            "  int(3)\n",
            "}\n",
            "array(3) {\n",
            "  [0]=>\n",
            "  int(3)\n",
            "  [1]=>\n",
            "  int(2)\n",
            "  [2]=>\n",
            "  int(1)\n",
            "}\n",
            "bool(true)\n",
            "bool(true)\n",
            "array_multisort(): Argument #3 must be an array or a sort flag that has not already been specified\n",
            "Array sizes are inconsistent\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_runtime_reference_for_variable(&runtime"));
    assert!(c_source.contains("ptn_call_function(&runtime, \"array_multisort\""));
}

#[test]
fn compile_array_multisort_mixed_object_order_to_native_binary() {
    let root = temp_dir("ptn-native-array-multisort-mixed-object-order");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-multisort-mixed-object-order.php");
    let output = root.join("array-multisort-mixed-object-order-bin");
    fs::write(
        &input,
        "<?php\n\
class A { public function __toString() { return \"A\"; } }\n\
class B {}\n\
$regular = [\"string\" => \"m\", \"a\" => new A, \"b\" => new B];\n\
var_dump(array_multisort($regular));\n\
foreach ($regular as $key => $value) { echo $key, \"\\n\"; }\n\
$numeric = [\"z\" => 0, \"a\" => new A, \"b\" => new B];\n\
var_dump(array_multisort($numeric, SORT_NUMERIC));\n\
foreach ($numeric as $key => $value) { echo $key, \"\\n\"; }",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "a\n",
            "string\n",
            "b\n",
            "\nWarning: Object of class A could not be converted to float in ptn on line 8\n",
            "\nWarning: Object of class A could not be converted to float in ptn on line 8\n",
            "\nWarning: Object of class B could not be converted to float in ptn on line 8\n",
            "bool(true)\n",
            "z\n",
            "a\n",
            "b\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_descending_sort_mutators_to_native_binary() {
    let root = temp_dir("ptn-native-descending-sort-mutators");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("descending-sort-mutators.php");
    let output = root.join("descending-sort-mutators-bin");
    fs::write(
        &input,
        "<?php\n\
$source = [\"b\" => 3, \"a\" => 1, \"c\" => 2];\n\
$copy = $source;\n\
var_dump(arsort($copy));\n\
foreach ($copy as $key => $value) {\n\
    echo $key, \"=\", $value, \"\\n\";\n\
}\n\
echo $source[\"b\"], \":\", $source[\"a\"], \":\", $source[\"c\"], \"\\n\";\n\
$keys = [3 => \"c\", 1 => \"a\", 2 => \"b\"];\n\
$key_copy = $keys;\n\
var_dump(krsort($key_copy));\n\
foreach ($key_copy as $key => $value) {\n\
    echo $key, \"=\", $value, \"\\n\";\n\
}\n\
$dynamic = \"arsort\";\n\
$dynamic_source = [\"low\" => 1, \"high\" => 9, \"mid\" => 5];\n\
$dynamic_copy = $dynamic_source;\n\
var_dump($dynamic($dynamic_copy));\n\
echo $dynamic_source[\"low\"], \":\", $dynamic_copy[\"high\"], \":\", key($dynamic_copy), \"\\n\";\n\
foreach ($dynamic_copy as $key => $value) {\n\
    echo $key, \"=\", $value, \"\\n\";\n\
}\n\
var_dump(function_exists(\"arsort\"), function_exists(\"krsort\"));",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "b=3\n",
            "c=2\n",
            "a=1\n",
            "3:1:2\n",
            "bool(true)\n",
            "3=c\n",
            "2=b\n",
            "1=a\n",
            "bool(true)\n",
            "1:9:high\n",
            "high=9\n",
            "mid=5\n",
            "low=1\n",
            "bool(true)\n",
            "bool(true)\n"
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_runtime_array_arsort_variable"));
    assert!(c_source.contains("ptn_runtime_array_krsort_variable"));
    assert!(c_source.contains("ptn_array_arsort_values"));
    assert!(c_source.contains("ptn_array_krsort_entries"));
}

