#[test]
fn compile_array_udiff_static_method_private_property_ternary_reducer_to_native_binary() {
    let root = temp_dir("ptn-native-array-udiff-private-property-ternary");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-udiff-private-property-ternary.php");
    let output = root.join("array-udiff-private-property-ternary-bin");
    fs::write(
        &input,
        "<?php
class Cr {
    private $priv_member;
    public $public_member;

    public function __construct($value) {
        $this->priv_member = $value;
        $this->public_member = $value;
    }

    public static function comp_func_cr($a, $b) {
        if ($a->priv_member === $b->priv_member) return 0;
        return ($a->priv_member > $b->priv_member) ? 1 : -1;
    }
}

$left = [new Cr(2), new Cr(5)];
$right = [new Cr(2)];
$result = array_udiff($left, $right, [\"Cr\", \"comp_func_cr\"]);
echo var_export($result, true), \"\\n\";
foreach ($result as $item) {
    echo $item->public_member, \"\\n\";
}
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "array (\n",
            "  1 => \n",
            "  \\Cr::__set_state(array(\n",
            "     'priv_member' => 5,\n",
            "     'public_member' => 5,\n",
            "  )),\n",
            ")\n",
            "5\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_array_udiff_variants_to_native_binary() {
    let root = temp_dir("ptn-native-array-udiff-variants");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-udiff-variants.php");
    let output = root.join("array-udiff-variants-bin");
    fs::write(
        &input,
        "<?php\n\
class Cmp {\n\
    public static function cmp($a, $b) {\n\
        if ($a === $b) return 0;\n\
        if ($a > $b) return 1;\n\
        return -1;\n\
    }\n\
}\n\
function cmp_values($a, $b) {\n\
    if ($a === $b) return 0;\n\
    if ($a > $b) return 1;\n\
    return -1;\n\
}\n\
function cmp_keys($a, $b) {\n\
    $a = (string)$a;\n\
    $b = (string)$b;\n\
    if ($a === $b) return 0;\n\
    if ($a > $b) return 1;\n\
    return -1;\n\
}\n\
$left = [\"a\" => 3, \"b\" => 2, 0 => 5, 1 => 7, \"drop\" => 9];\n\
$right = [\"x\" => 2, 0 => 5, 1 => 8, \"drop\" => 9];\n\
var_dump(array_udiff($left, $right, [\"Cmp\", \"cmp\"]));\n\
var_dump(array_udiff_assoc($left, $right, \"cmp_values\"));\n\
var_dump(array_udiff_uassoc($left, [\"a\" => 3, \"B\" => 2, 0 => 5, 2 => 7, \"drop\" => 9], [\"Cmp\", \"cmp\"], \"cmp_keys\"));\n\
var_dump(function_exists(\"array_udiff\"), function_exists(\"ARRAY_UDIFF_ASSOC\"), function_exists(\"array_udiff_uassoc\"));",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "array(2) {\n",
            "  [\"a\"]=>\n",
            "  int(3)\n",
            "  [1]=>\n",
            "  int(7)\n",
            "}\n",
            "array(3) {\n",
            "  [\"a\"]=>\n",
            "  int(3)\n",
            "  [\"b\"]=>\n",
            "  int(2)\n",
            "  [1]=>\n",
            "  int(7)\n",
            "}\n",
            "array(2) {\n",
            "  [\"b\"]=>\n",
            "  int(2)\n",
            "  [1]=>\n",
            "  int(7)\n",
            "}\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_array_udiff"));
    assert!(c_source.contains("ptn_internal_array_udiff_assoc"));
    assert!(c_source.contains("ptn_internal_array_udiff_uassoc"));
}

#[test]
fn compile_array_key_and_callback_set_operations_to_native_binary() {
    let root = temp_dir("ptn-native-array-key-callback-set-operations");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-key-callback-set-operations.php");
    let output = root.join("array-key-callback-set-operations-bin");
    fs::write(
        &input,
        "<?php\n\
function cmp_value($a, $b) {\n\
    if ($a === $b) return 0;\n\
    return ($a > $b) ? 1 : -1;\n\
}\n\
function cmp_key($a, $b) {\n\
    $a = (string)$a;\n\
    $b = (string)$b;\n\
    if ($a === $b) return 0;\n\
    return ($a > $b) ? 1 : -1;\n\
}\n\
$left = [\"a\" => \"green\", \"b\" => \"brown\", \"c\" => \"blue\", 0 => \"red\", 4 => \"four\"];\n\
$right = [\"a\" => \"green\", \"x\" => \"brown\", 0 => \"red\", 4 => \"changed\"];\n\
$third = [\"a\" => \"green\", 0 => \"other\", 9 => \"red\", \"b\" => \"brown\"];\n\
var_dump(array_diff_key($left, $right));\n\
var_dump(array_intersect_key($left, $right, $third));\n\
var_dump(array_diff_uassoc($left, $right, \"cmp_key\"));\n\
var_dump(array_diff_ukey($left, $right, \"cmp_key\"));\n\
var_dump(array_intersect_uassoc($left, $right, $third, \"cmp_key\"));\n\
var_dump(array_intersect_ukey($left, $right, $third, \"cmp_key\"));\n\
var_dump(array_uintersect($left, [\"n\" => \"brown\", \"m\" => \"red\"], \"cmp_value\"));\n\
var_dump(array_uintersect_assoc($left, [\"a\" => \"green\", \"b\" => \"other\", 0 => \"red\"], \"cmp_value\"));\n\
var_dump(array_uintersect_uassoc($left, [\"A\" => \"green\", \"b\" => \"brown\", 0 => \"red\"], \"cmp_value\", \"cmp_key\"));\n\
var_dump(function_exists(\"array_diff_key\"), function_exists(\"ARRAY_UINTERSECT_UASSOC\"));",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "array(2) {\n",
            "  [\"b\"]=>\n",
            "  string(5) \"brown\"\n",
            "  [\"c\"]=>\n",
            "  string(4) \"blue\"\n",
            "}\n",
            "array(2) {\n",
            "  [\"a\"]=>\n",
            "  string(5) \"green\"\n",
            "  [0]=>\n",
            "  string(3) \"red\"\n",
            "}\n",
            "array(3) {\n",
            "  [\"b\"]=>\n",
            "  string(5) \"brown\"\n",
            "  [\"c\"]=>\n",
            "  string(4) \"blue\"\n",
            "  [4]=>\n",
            "  string(4) \"four\"\n",
            "}\n",
            "array(2) {\n",
            "  [\"b\"]=>\n",
            "  string(5) \"brown\"\n",
            "  [\"c\"]=>\n",
            "  string(4) \"blue\"\n",
            "}\n",
            "array(1) {\n",
            "  [\"a\"]=>\n",
            "  string(5) \"green\"\n",
            "}\n",
            "array(2) {\n",
            "  [\"a\"]=>\n",
            "  string(5) \"green\"\n",
            "  [0]=>\n",
            "  string(3) \"red\"\n",
            "}\n",
            "array(2) {\n",
            "  [\"b\"]=>\n",
            "  string(5) \"brown\"\n",
            "  [0]=>\n",
            "  string(3) \"red\"\n",
            "}\n",
            "array(2) {\n",
            "  [\"a\"]=>\n",
            "  string(5) \"green\"\n",
            "  [0]=>\n",
            "  string(3) \"red\"\n",
            "}\n",
            "array(2) {\n",
            "  [\"b\"]=>\n",
            "  string(5) \"brown\"\n",
            "  [0]=>\n",
            "  string(3) \"red\"\n",
            "}\n",
            "bool(true)\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_array_diff_key"));
    assert!(c_source.contains("ptn_internal_array_intersect_key"));
    assert!(c_source.contains("ptn_internal_array_diff_uassoc"));
    assert!(c_source.contains("ptn_internal_array_intersect_ukey"));
    assert!(c_source.contains("ptn_internal_array_uintersect_uassoc"));
}

#[test]
fn compile_array_merge_recursive_to_native_binary() {
    let root = temp_dir("ptn-native-array-merge-recursive");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-merge-recursive.php");
    let output = root.join("array-merge-recursive-bin");
    fs::write(
        &input,
        "<?php\n\
var_dump(array_merge_recursive());\n\
$left = [1, [1, 2]];\n\
$right = [3, [\"hello\", \"world\"]];\n\
var_dump(array_merge_recursive($left, $right));\n\
$assoc_left = [\"k\" => \"left\", \"both\" => [\"x\" => 1]];\n\
$assoc_right = [\"k\" => \"right\", \"both\" => [\"y\" => 2]];\n\
$assoc = array_merge_recursive($assoc_left, $assoc_right);\n\
$assoc[\"both\"][\"x\"] = 9;\n\
var_dump($assoc);\n\
var_dump($assoc_left[\"both\"][\"x\"], $assoc_right[\"both\"][\"y\"], function_exists(\"array_merge_recursive\"));\n\
try { array_merge_recursive(1); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }\n\
try { array_merge_recursive([], 1); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }\n\
try { array_merge_recursive(['' => [9223372036854775807 => null]], ['' => [null]]); } catch (Throwable $e) { echo $e->getMessage(), \"\\n\"; }\n\
try { array_merge_recursive(['foo' => [9223372036854775807 => null]], ['foo' => str_repeat('a', 2)]); } catch (Throwable $e) { echo $e->getMessage(), \"\\n\"; }",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "array(0) {\n",
            "}\n",
            "array(4) {\n",
            "  [0]=>\n",
            "  int(1)\n",
            "  [1]=>\n",
            "  array(2) {\n",
            "    [0]=>\n",
            "    int(1)\n",
            "    [1]=>\n",
            "    int(2)\n",
            "  }\n",
            "  [2]=>\n",
            "  int(3)\n",
            "  [3]=>\n",
            "  array(2) {\n",
            "    [0]=>\n",
            "    string(5) \"hello\"\n",
            "    [1]=>\n",
            "    string(5) \"world\"\n",
            "  }\n",
            "}\n",
            "array(2) {\n",
            "  [\"k\"]=>\n",
            "  array(2) {\n",
            "    [0]=>\n",
            "    string(4) \"left\"\n",
            "    [1]=>\n",
            "    string(5) \"right\"\n",
            "  }\n",
            "  [\"both\"]=>\n",
            "  array(2) {\n",
            "    [\"x\"]=>\n",
            "    int(9)\n",
            "    [\"y\"]=>\n",
            "    int(2)\n",
            "  }\n",
            "}\n",
            "int(1)\n",
            "int(2)\n",
            "bool(true)\n",
            "array_merge_recursive(): Argument #1 must be of type array, int given\n",
            "array_merge_recursive(): Argument #2 must be of type array, int given\n",
            "Cannot add element to the array as the next element is already occupied\n",
            "Cannot add element to the array as the next element is already occupied\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_array_merge_recursive"));
    assert!(c_source.contains("ptn_array_merge_recursive_into"));
}

#[test]
fn compile_array_replace_recursive_to_native_binary() {
    let root = temp_dir("ptn-native-array-replace-recursive");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-replace-recursive.php");
    let output = root.join("array-replace-recursive-bin");
    fs::write(
        &input,
        "<?php\n\
$x = 24;\n\
$left = [[42], \"old\"];\n\
$right = [[&$x], \"new\"];\n\
unset($x);\n\
$merged = array_replace_recursive($left, $right);\n\
$right[0][0] = 12;\n\
$merged[0][] = \"tail\";\n\
var_dump($merged, $left, $right, function_exists(\"array_replace_recursive\"));",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "array(2) {\n",
            "  [0]=>\n",
            "  array(2) {\n",
            "    [0]=>\n",
            "    int(24)\n",
            "    [1]=>\n",
            "    string(4) \"tail\"\n",
            "  }\n",
            "  [1]=>\n",
            "  string(3) \"new\"\n",
            "}\n",
            "array(2) {\n",
            "  [0]=>\n",
            "  array(1) {\n",
            "    [0]=>\n",
            "    int(42)\n",
            "  }\n",
            "  [1]=>\n",
            "  string(3) \"old\"\n",
            "}\n",
            "array(2) {\n",
            "  [0]=>\n",
            "  array(1) {\n",
            "    [0]=>\n",
            "    int(12)\n",
            "  }\n",
            "  [1]=>\n",
            "  string(3) \"new\"\n",
            "}\n",
            "bool(true)\n"
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_array_replace_recursive"));
    assert!(c_source.contains("ptn_array_replace_recursive_into"));
}

#[test]
fn compile_array_replace_to_native_binary() {
    let root = temp_dir("ptn-native-array-replace");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-replace.php");
    let output = root.join("array-replace-bin");
    fs::write(
        &input,
        "<?php\n\
$x = 24;\n\
$left = [0 => \"zero\", \"keep\" => [\"left\"], 10 => \"ten\", \"ref\" => &$x];\n\
$right = [0 => \"changed\", \"keep\" => [\"right\"], 5 => \"five\", \"ref\" => \"new\"];\n\
unset($x);\n\
$replaced = array_replace($left, $right);\n\
$right[\"keep\"][] = \"mutated\";\n\
$replaced[\"keep\"][] = \"tail\";\n\
var_dump($replaced, $left, $right, function_exists(\"array_replace\"), function_exists(\"ARRAY_REPLACE\"));",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "array(5) {\n",
            "  [0]=>\n",
            "  string(7) \"changed\"\n",
            "  [\"keep\"]=>\n",
            "  array(2) {\n",
            "    [0]=>\n",
            "    string(5) \"right\"\n",
            "    [1]=>\n",
            "    string(4) \"tail\"\n",
            "  }\n",
            "  [10]=>\n",
            "  string(3) \"ten\"\n",
            "  [\"ref\"]=>\n",
            "  string(3) \"new\"\n",
            "  [5]=>\n",
            "  string(4) \"five\"\n",
            "}\n",
            "array(4) {\n",
            "  [0]=>\n",
            "  string(4) \"zero\"\n",
            "  [\"keep\"]=>\n",
            "  array(1) {\n",
            "    [0]=>\n",
            "    string(4) \"left\"\n",
            "  }\n",
            "  [10]=>\n",
            "  string(3) \"ten\"\n",
            "  [\"ref\"]=>\n",
            "  int(24)\n",
            "}\n",
            "array(4) {\n",
            "  [0]=>\n",
            "  string(7) \"changed\"\n",
            "  [\"keep\"]=>\n",
            "  array(2) {\n",
            "    [0]=>\n",
            "    string(5) \"right\"\n",
            "    [1]=>\n",
            "    string(7) \"mutated\"\n",
            "  }\n",
            "  [5]=>\n",
            "  string(4) \"five\"\n",
            "  [\"ref\"]=>\n",
            "  string(3) \"new\"\n",
            "}\n",
            "bool(true)\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_array_replace"));
    assert!(c_source.contains("ptn_array_replace_into"));
}

#[test]
fn compile_array_replace_preserves_shared_references_to_native_binary() {
    let root = temp_dir("ptn-native-array-replace-shared-references");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-replace-shared-references.php");
    let output = root.join("array-replace-shared-references-bin");
    fs::write(
        &input,
        "<?php\n\
$x = 1;\n\
$right = [\"r\" => &$x, \"n\" => [\"r\" => &$x]];\n\
$replaced = array_replace([], $right);\n\
$recursive = array_replace_recursive([\"n\" => [\"keep\" => 0]], $right);\n\
$x = 2;\n\
$replaced[\"r\"] = 3;\n\
$recursive[\"n\"][\"r\"] = 4;\n\
var_dump($x, $right, $replaced, $recursive);\n\
$one = [1];\n\
$two = [42];\n\
$left = [\"k\" => &$one];\n\
$replacement = [\"k\" => &$two];\n\
array_replace_recursive($left, $replacement);\n\
var_dump(current($one), current($two));\n\
$one = [1];\n\
$two = [42];\n\
$arr1 = [\"k\" => &$one];\n\
$arr2 = [\"k\" => &$two];\n\
array_merge_recursive($arr1, $arr2);\n\
var_dump(current($one), current($two));",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();
    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "int(4)\n",
            "array(2) {\n",
            "  [\"r\"]=>\n",
            "  &int(4)\n",
            "  [\"n\"]=>\n",
            "  array(1) {\n",
            "    [\"r\"]=>\n",
            "    &int(4)\n",
            "  }\n",
            "}\n",
            "array(2) {\n",
            "  [\"r\"]=>\n",
            "  &int(4)\n",
            "  [\"n\"]=>\n",
            "  array(1) {\n",
            "    [\"r\"]=>\n",
            "    &int(4)\n",
            "  }\n",
            "}\n",
            "array(2) {\n",
            "  [\"n\"]=>\n",
            "  array(2) {\n",
            "    [\"keep\"]=>\n",
            "    int(0)\n",
            "    [\"r\"]=>\n",
            "    &int(4)\n",
            "  }\n",
            "  [\"r\"]=>\n",
            "  &int(4)\n",
            "}\n",
            "int(1)\n",
            "int(42)\n",
            "int(1)\n",
            "int(42)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

