#[test]
fn compile_alternative_control_flow_to_native_binary() {
    let root = temp_dir("ptn-native-alternative-control-flow");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("alternative-control-flow.php");
    let output = root.join("alternative-control-flow-bin");
    fs::write(
        &input,
        "<?php
$out = '';
if (false):
    $out .= 'bad';
elseif (true):
    $out .= 'if';
else:
    $out .= 'bad';
endif;
for ($i = 0; $i < 3; $i++):
    $out .= $i;
endfor;
foreach ([1, 2] as $value):
    $out .= $value;
endforeach;
switch ($value):
    case 1:
        $out .= 'bad';
        break;
    case 2:
        $out .= 'switch';
        break;
    default:
        $out .= 'bad';
endswitch;
echo $out, \"\\n\";
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "if01212switch\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

