#[test]
fn compile_arrow_functions_to_native_binary() {
    let root = temp_dir("ptn-native-arrow-functions");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("arrow-functions.php");
    let output = root.join("arrow-functions-bin");
    fs::write(
        &input,
        "<?php
$x = 5;
$copy = fn() => ++$x;
var_dump($copy());
var_dump($x);
$refSource = 1;
$refFn = fn&(&$value) => $value;
$ref =& $refFn($refSource);
$ref++;
var_dump($refSource);
$outer = 6;
var_dump((fn() => fn() => $outer)()());
$missingFn = fn() => $missing;
echo \"made\\n\";
var_dump($missingFn());
class ArrowThis {
    public function run() {
        $fn = fn() => isset($this);
        $static = static fn() => isset($this);
        var_dump($fn(), $static());
    }
}
(new ArrowThis())->run();
$adder = fn(int $x, int ...$rest): int => $x + array_sum($rest);
var_dump($adder(\"3\", 4, 5));
$object = new stdClass;
$object->name = \"captured\";
$propertyText = fn() => \"name={$object->name}\\n\";
echo $propertyText();
$object->name = \"changed\";
echo $propertyText();
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        format!(
            "int(6)\nint(5)\nint(2)\nint(6)\nmade\n{}NULL\nbool(true)\nbool(false)\nint(12)\nname=captured\nname=changed\n",
            undefined_variable_warning(&input, "missing", 13)
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_closure("));
    assert!(c_source.contains("ptn_runtime_read_variable_quiet(&runtime, \"outer\")"));
    assert!(c_source.contains("ptn_runtime_read_variable_quiet(&runtime, \"this\")"));
}

