#[test]
fn parser_accepts_stdclass_property_reads_and_writes() {
    let program = parser::parse(
        "<?php\n\
$object = new stdClass;\n\
$object->value = 7;\n\
echo $object->value;\n\
$object->missing ??= 8;\n",
    )
    .unwrap();
    assert_eq!(program.statements.len(), 4);

    let Statement::Expression { expression, .. } = &program.statements[1] else {
        panic!("expected property assignment expression statement");
    };
    assert!(matches!(
        expression,
        Expr::Assign {
            target: AssignmentTarget::Property { name, .. },
            ..
        } if name == "value"
    ));

    let Statement::Echo { expressions, .. } = &program.statements[2] else {
        panic!("expected echo statement");
    };
    assert!(matches!(
        &expressions[0],
        Expr::PropertyFetch { name, .. } if name == "value"
    ));

    let Statement::Expression { expression, .. } = &program.statements[3] else {
        panic!("expected property null coalescing assignment expression statement");
    };
    assert!(matches!(
        expression,
        Expr::Assign {
            target: AssignmentTarget::Property { name, .. },
            op: AssignmentOp::CoalesceAssign,
            ..
        } if name == "missing"
    ));
}

#[test]
fn parser_accepts_dynamic_property_and_method_dispatch() {
    let program = parser::parse(
        "<?php\n\
$object->$name = 7;\n\
echo $object->$name;\n\
$object->{$name . \"_suffix\"} = 8;\n\
$object->$method();\n\
Example::$method();\n\
Example::{$method}();\n\
$object::$method();\n\
$object::{\"method\"}();\n",
    )
    .unwrap();
    assert_eq!(program.statements.len(), 8);

    let Statement::Expression { expression, .. } = &program.statements[0] else {
        panic!("expected dynamic property assignment expression");
    };
    assert!(matches!(
        expression,
        Expr::Assign {
            target: AssignmentTarget::DynamicProperty { name, .. },
            op: AssignmentOp::Assign,
            ..
        } if matches!(name.as_ref(), Expr::Variable(variable, _) if variable == "name")
    ));

    let Statement::Echo { expressions, .. } = &program.statements[1] else {
        panic!("expected echo statement");
    };
    assert!(matches!(
        &expressions[0],
        Expr::DynamicPropertyFetch { name, .. }
            if matches!(name.as_ref(), Expr::Variable(variable, _) if variable == "name")
    ));

    let Statement::Expression { expression, .. } = &program.statements[3] else {
        panic!("expected dynamic method call expression");
    };
    assert!(matches!(expression, Expr::DynamicMethodCall { .. }));

    for index in 4..=7 {
        let Statement::Expression { expression, .. } = &program.statements[index] else {
            panic!("expected dynamic static call expression");
        };
        assert!(matches!(expression, Expr::DynamicCall { .. }));
    }
}

