#[test]
fn compile_stdclass_property_null_coalescing_assignment_to_native_binary() {
    let root = temp_dir("ptn-native-stdclass-property-coalesce-assign");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("stdclass-property-coalesce-assign.php");
    let output = root.join("stdclass-property-coalesce-assign-bin");
    fs::write(
        &input,
        "<?php
function receiver($object, $label) {
    echo \"receiver:$label\\n\";
    return $object;
}
function rhs($label) {
    echo \"rhs:$label\\n\";
    return $label;
}

$object = new stdClass;
var_dump(receiver($object, \"missing\")->missing ??= rhs(\"missing\"));
$object->nullish = null;
var_dump(receiver($object, \"nullish\")->nullish ??= rhs(\"nullish\"));
$object->hit = \"kept\";
var_dump(receiver($object, \"hit\")->hit ??= rhs(\"hit\"));
var_dump($object->missing, $object->nullish, $object->hit);

$scalar = 3;
try {
    var_dump($scalar->bad ??= rhs(\"bad\"));
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "receiver:missing\n\
rhs:missing\n\
receiver:missing\n\
string(7) \"missing\"\n\
receiver:nullish\n\
rhs:nullish\n\
receiver:nullish\n\
string(7) \"nullish\"\n\
receiver:hit\n\
string(4) \"kept\"\n\
string(7) \"missing\"\n\
string(7) \"nullish\"\n\
string(4) \"kept\"\n\
rhs:bad\n\
Attempt to assign property \"bad\" on int\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_object_property_lookup_quiet(&runtime"));
    assert!(c_source.contains("ptn_object_write_property(&runtime"));
}

#[test]
fn compile_property_isset_empty_and_coalesce_to_native_binary() {
    let root = temp_dir("ptn-native-property-isset-empty-coalesce");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("property-isset-empty-coalesce.php");
    let output = root.join("property-isset-empty-coalesce-bin");
    fs::write(
        &input,
        "<?php
class C {
    private $secret = 1;

    public function probe() {
        var_dump(isset($this->secret), empty($this->secret), $this->secret ?? \"fallback\");
    }
}

function receiver($object, $label) {
    echo \"receiver:$label\\n\";
    return $object;
}

$object = new stdClass();
$object->x = null;
$object->zero = \"0\";
$object->truthy = 5;
var_dump(isset(receiver($object, \"truthy\")->truthy));
var_dump(isset(receiver($object, \"nullish\")->x));
var_dump(isset(receiver($object, \"missing\")->missing));
var_dump(empty(receiver($object, \"zero\")->zero));
var_dump(empty(receiver($object, \"truthy-empty\")->truthy));
var_dump(empty(receiver($object, \"missing-empty\")->missing));
var_dump(receiver($object, \"coalesce-hit\")->truthy ?? \"fallback\");
var_dump(receiver($object, \"coalesce-null\")->x ?? \"fallback\");
var_dump(receiver($object, \"coalesce-missing\")->missing ?? \"fallback\");

$scalar = 3;
var_dump(isset($scalar->prop), empty($scalar->prop), $scalar->prop ?? \"fallback\");

$declared = new C();
$declared->probe();
var_dump(isset($declared->secret), empty($declared->secret), $declared->secret ?? \"fallback\");
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "receiver:truthy\n",
            "bool(true)\n",
            "receiver:nullish\n",
            "bool(false)\n",
            "receiver:missing\n",
            "bool(false)\n",
            "receiver:zero\n",
            "bool(true)\n",
            "receiver:truthy-empty\n",
            "bool(false)\n",
            "receiver:missing-empty\n",
            "bool(true)\n",
            "receiver:coalesce-hit\n",
            "int(5)\n",
            "receiver:coalesce-null\n",
            "string(8) \"fallback\"\n",
            "receiver:coalesce-missing\n",
            "string(8) \"fallback\"\n",
            "bool(false)\n",
            "bool(true)\n",
            "string(8) \"fallback\"\n",
            "bool(true)\n",
            "bool(false)\n",
            "int(1)\n",
            "bool(false)\n",
            "bool(true)\n",
            "string(8) \"fallback\"\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_object_property_probe_quiet(&runtime"));
}

#[test]
fn compile_class_constant_reads_to_native_binary() {
    let root = temp_dir("ptn-native-class-constant-reads");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("class-constant-reads.php");
    let output = root.join("class-constant-reads-bin");
    fs::write(
        &input,
        "<?php
class Sample {
    const X = 42, Data = [\"answer\" => 42];
    const Extracted = [\"bar\" => 3][\"bar\"];
    public const Label = \"hello\";

    public static function label() {
        return self::Label;
    }
}

echo Sample::X, \"\\n\";
var_dump(Sample::Data);
var_dump(Sample::Extracted);
echo Sample::label(), \"\\n\";
var_dump(defined(\"sample::Label\"), constant(\"sample::Label\"));
var_dump(ArrayObject::STD_PROP_LIST, \\ArrayObject::ARRAY_AS_PROPS, constant(\"arrayobject::STD_PROP_LIST\"), defined(\"ArrayObject::ARRAY_AS_PROPS\"));
try {
    var_dump(Sample::label);
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "42\n",
            "array(1) {\n",
            "  [\"answer\"]=>\n",
            "  int(42)\n",
            "}\n",
            "int(3)\n",
            "hello\n",
            "bool(true)\n",
            "string(5) \"hello\"\n",
            "int(1)\n",
            "int(2)\n",
            "int(1)\n",
            "bool(true)\n",
            "Undefined constant Sample::label\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_runtime_define_class_constant(&runtime"));
    assert!(c_source.contains("ptn_runtime_read_class_constant(&runtime"));
}

#[test]
fn compile_deprecated_class_constant_reads_to_native_binary() {
    let root = temp_dir("ptn-native-deprecated-class-constant-reads");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("deprecated-class-constant-reads.php");
    let output = root.join("deprecated-class-constant-reads-bin");
    fs::write(
        &input,
        "<?php
class Clazz {
    #[Deprecated]
    public const TEST = 1;
    #[Deprecated(\"use Clazz::TEST instead\")]
    public const TEST2 = 2;
    #[Deprecated]
    public const TEST3 = 3;
    public const MESSAGE = \"constant message\";
    #[Deprecated(self::MESSAGE)]
    public const TEST4 = 4;
    #[Deprecated(self::TEST5)]
    public const TEST5 = \"self message\";
}
var_dump(Clazz::TEST);
var_dump(constant('Clazz::TEST2'));
var_dump(defined('Clazz::TEST3'));
var_dump(Clazz::TEST4);
var_dump(Clazz::TEST5);
class D {
    #[Deprecated(Alias::C)]
    public const C = \"alias message\";
}
class_alias('D', 'Alias');
var_dump(D::C);
define('SUFFIX', random_int(1, 2) === 1 ? 'a' : 'b');
class RuntimeUnknown {
    #[Deprecated]
    public const VALUE = self::class . '-' . SUFFIX;
}
$value = RuntimeUnknown::VALUE;
var_dump($value === 'RuntimeUnknown-' . SUFFIX);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "\nDeprecated: Constant Clazz::TEST is deprecated in ptn on line 15\n",
            "int(1)\n",
            "\nDeprecated: Constant Clazz::TEST2 is deprecated, use Clazz::TEST instead in ptn on line 16\n",
            "int(2)\n",
            "bool(true)\n",
            "\nDeprecated: Constant Clazz::TEST4 is deprecated, constant message in ptn on line 18\n",
            "int(4)\n",
            "\nDeprecated: Constant Clazz::TEST5 is deprecated, self message in ptn on line 19\n",
            "string(12) \"self message\"\n",
            "\nDeprecated: Constant D::C is deprecated, alias message in ptn on line 25\n",
            "string(13) \"alias message\"\n",
            "\nDeprecated: Constant RuntimeUnknown::VALUE is deprecated in ptn on line 31\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_runtime_define_class_constant_deprecation(&runtime"));
    assert!(c_source.contains("Constant Clazz::TEST4 is deprecated, constant message"));
    assert!(c_source.contains("Constant Clazz::TEST5 is deprecated, self message"));
}

#[test]
fn compile_class_name_fetches_to_native_binary() {
    let root = temp_dir("ptn-native-class-name-fetches");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("class-name-fetches.php");
    let output = root.join("class-name-fetches-bin");
    fs::write(
        &input,
        "<?php
class Worker {}

$worker = new Worker();
$std = new stdClass();
$callback = function () { return null; };

try {
    throw new ValueError('bad');
} catch (Throwable $e) {
    echo $e::class, ':', $e->getMessage(), \"\\n\";
}

$name = $worker::class;
unset($worker);
echo $name, \"\\n\";
echo $std::CLASS, \"\\n\";
echo $callback::class, \"\\n\";
echo Worker::class, \"\\n\";
echo worker::class, \"\\n\";
echo \\stdClass::class, \"\\n\";

$className = 'Worker';
try {
    echo $className::class, \"\\n\";
} catch (TypeError $e) {
    echo $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "ValueError:bad\n",
            "Worker\n",
            "stdClass\n",
            "Closure\n",
            "Worker\n",
            "worker\n",
            "stdClass\n",
            "Cannot use \"::class\" on value of type string\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_runtime_fetch_dynamic_class_name(&runtime"));
    assert!(c_source.contains("ptn_string(\"Worker\")"));
}

