    fs::write(
        &input,
        "<?php
class Box {
    public $value = 1;
    private $secret = 4;
    public static $count = 1;

    public function bump() {
        var_dump($this->secret++);
        var_dump(++$this->secret);
    }

    public static function bumpStatic() {
        var_dump(self::$count++);
        var_dump(++self::$count);
    }
}

$box = new Box();
var_dump($box->value++);
var_dump($box->value);
var_dump(++$box->value);
$box->value--;
var_dump($box->value);
$box->bump();
var_dump(Box::$count++);
var_dump(++Box::$count);
Box::$count--;
var_dump(Box::$count);
Box::bumpStatic();
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
