#[test]
fn compile_static_property_array_dim_assignments_to_native_binary() {
    let root = temp_dir("ptn-native-static-property-array-dim-assignments");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("static-property-array-dim-assignments.php");
    let output = root.join("static-property-array-dim-assignments-bin");
    fs::write(
        &input,
        "<?php
class Store {
    public static $items = [\"a\" => 1];

    public static function mutate() {
        self::$items[\"a\"] += 2;
        self::$items[\"b\"] = 4;
        self::$items[\"a\"] = 9;
    }
}

Store::$items[\"c\"] = 5;
Store::mutate();
var_dump(Store::$items);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "array(3) {\n",
            "  [\"a\"]=>\n",
            "  int(9)\n",
            "  [\"c\"]=>\n",
            "  int(5)\n",
            "  [\"b\"]=>\n",
            "  int(4)\n",
            "}\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_value_array_path_set(&runtime"));
    assert!(c_source.contains("ptn_value_array_path_set_from_assign_op(&runtime"));
    assert!(c_source.contains("ptn_runtime_read_static_property(&runtime"));
    assert!(c_source.contains("ptn_runtime_write_static_property_indirect(&runtime"));
}

#[test]
fn compile_dynamic_static_property_array_dim_assignments_to_native_binary() {
    let root = temp_dir("ptn-native-dynamic-static-property-array-dim-assignments");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dynamic-static-property-array-dim-assignments.php");
    let output = root.join("dynamic-static-property-array-dim-assignments-bin");
    fs::write(
        &input,
        "<?php
class DynamicStaticStore {
    private static $items = [\"seed\" => 1];

    public function mutate() {
        $this::$items[] = 2;
        $this::$items[\"seed\"] += 4;
        var_dump($this::$items);
    }
}

(new DynamicStaticStore())->mutate();
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "array(2) {\n",
            "  [\"seed\"]=>\n",
            "  int(5)\n",
            "  [0]=>\n",
            "  int(2)\n",
            "}\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_static_property_isset_empty_and_coalesce_to_native_binary() {
    let root = temp_dir("ptn-native-static-property-isset-empty-coalesce");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("static-property-isset-empty-coalesce.php");
    let output = root.join("static-property-isset-empty-coalesce-bin");
    fs::write(
        &input,
        "<?php
class Counter {
    public static $nullish = null;
    public static $zero = \"0\";
    public static $truthy = 5;

    public static function probe() {
        var_dump(isset(self::$truthy), empty(self::$zero), self::$missing ?? \"fallback\");
    }
}

var_dump(isset(Counter::$truthy), isset(Counter::$nullish), isset(Counter::$missing));
var_dump(empty(Counter::$zero), empty(Counter::$truthy), empty(Counter::$missing));
var_dump(Counter::$truthy ?? \"fallback\", Counter::$nullish ?? \"fallback\", Counter::$missing ?? \"fallback\");
Counter::probe();
try {
    echo Counter::$missing;
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "bool(false)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
            "int(5)\n",
            "string(8) \"fallback\"\n",
            "string(8) \"fallback\"\n",
            "bool(true)\n",
            "bool(true)\n",
            "string(8) \"fallback\"\n",
            "Access to undeclared static property Counter::$missing\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_runtime_read_static_property_quiet(&runtime"));
    assert!(c_source.contains("ptn_runtime_read_static_property(&runtime"));
}

#[test]
fn compile_static_property_null_coalescing_assignment_to_native_binary() {
    let root = temp_dir("ptn-native-static-property-coalesce-assign");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("static-property-coalesce-assign.php");
    let output = root.join("static-property-coalesce-assign-bin");
    fs::write(
        &input,
        "<?php
class Counter {
    public static $nullish = null;
    public static $hit = \"kept\";
    public static $selfValue;

    public static function initSelf() {
        var_dump(self::$selfValue ??= rhs(\"self\"));
        var_dump(self::$selfValue ??= rhs(\"self-hit\"));
    }
}

function rhs($label) {
    echo \"rhs:$label\\n\";
    return $label;
}

var_dump(Counter::$nullish ??= rhs(\"nullish\"));
var_dump(Counter::$hit ??= rhs(\"hit\"));
var_dump(Counter::$nullish, Counter::$hit);
Counter::initSelf();
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "rhs:nullish\n",
            "string(7) \"nullish\"\n",
            "string(4) \"kept\"\n",
            "string(7) \"nullish\"\n",
            "string(4) \"kept\"\n",
            "rhs:self\n",
            "string(4) \"self\"\n",
            "string(4) \"self\"\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_runtime_read_static_property_quiet(&runtime"));
    assert!(c_source.contains("ptn_runtime_write_static_property(&runtime"));
}

