#[test]
fn compile_asymmetric_property_indirect_write_and_unset_diagnostics_to_native_binary() {
    let root = temp_dir("ptn-native-asymmetric-property-indirect-unset");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("asymmetric-property-indirect-unset.php");
    let output = root.join("asymmetric-property-indirect-unset-bin");
    fs::write(
        &input,
        "<?php
class Bag {
    public private(set) array $items = [1];
    public protected(set) string $name = \"draft\";
    public private(set) string $secret = \"hidden\";

    public function appendItem($value) {
        $this->items[] = $value;
    }

    public function unsetItem() {
        unset($this->items[0]);
    }

    public function unsetName() {
        unset($this->name);
    }
}

class ChildBag extends Bag {
    public function unsetNameFromChild() {
        unset($this->name);
    }

    public function unsetSecretFromChild() {
        unset($this->secret);
    }
}

$bag = new ChildBag();
try {
    $bag->items[] = 2;
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
var_dump($bag->items);
$bag->appendItem(2);
var_dump($bag->items);
try {
    unset($bag->items[0]);
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
var_dump($bag->items);
$bag->unsetItem();
var_dump($bag->items);
try {
    unset($bag->name);
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
var_dump($bag->name ?? 'unset');
$bag->unsetNameFromChild();
var_dump($bag->name ?? 'unset');
try {
    $bag->unsetSecretFromChild();
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
var_dump($bag->secret ?? 'unset');
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "Cannot indirectly modify private(set) property Bag::$items from global scope\n",
            "array(1) {\n",
            "  [0]=>\n",
            "  int(1)\n",
            "}\n",
            "array(2) {\n",
            "  [0]=>\n",
            "  int(1)\n",
            "  [1]=>\n",
            "  int(2)\n",
            "}\n",
            "Cannot indirectly modify private(set) property Bag::$items from global scope\n",
            "array(2) {\n",
            "  [0]=>\n",
            "  int(1)\n",
            "  [1]=>\n",
            "  int(2)\n",
            "}\n",
            "array(1) {\n",
            "  [1]=>\n",
            "  int(2)\n",
            "}\n",
            "Cannot unset protected(set) property Bag::$name from global scope\n",
            "string(5) \"draft\"\n",
            "string(5) \"unset\"\n",
            "Cannot unset private(set) property Bag::$secret from scope ChildBag\n",
            "string(6) \"hidden\"\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_object_write_property_indirect"));
    assert!(c_source.contains("ptn_throw_property_unset_visibility_error"));
}

#[test]
fn compile_nested_asymmetric_uninitialized_property_diagnostics_to_native_binary() {
    let root = temp_dir("ptn-native-nested-asymmetric-uninitialized-property");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("nested-asymmetric-uninitialized-property.php");
    let output = root.join("nested-asymmetric-uninitialized-property-bin");
    fs::write(
        &input,
        "<?php
class Inner {
    public int $prop = 1;
    public array $array = [];
}

class Test {
    public private(set) Inner $prop;

    public function init() {
        $this->prop = new Inner();
    }
}

function r($test) { echo $test->prop->prop; }
function w($test) { $test->prop->prop = 0; echo 'done'; }
function rw($test) { $test->prop->prop += 1; echo 'done'; }
function im($test) { $test->prop->array[] = 1; echo 'done'; }
function is($test) { echo (int) isset($test->prop->prop); }
function us($test) { unset($test->prop->prop); echo 'done'; }
function us_dim($test) { unset($test->prop->array[0]); echo 'done'; }

foreach ([true, false] as $init) {
    foreach (['r', 'w', 'rw', 'im', 'is', 'us', 'us_dim'] as $op) {
        $test = new Test();
        if ($init) {
            $test->init();
        }
        echo 'Init: ' . ((int) $init) . ', op: ' . $op . ': ';
        try {
            $op($test);
        } catch (Error $e) {
            echo $e->getMessage();
        }
        echo \"\\n\";
    }
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "Init: 1, op: r: 1\n",
            "Init: 1, op: w: done\n",
            "Init: 1, op: rw: done\n",
            "Init: 1, op: im: done\n",
            "Init: 1, op: is: 1\n",
            "Init: 1, op: us: done\n",
            "Init: 1, op: us_dim: done\n",
            "Init: 0, op: r: Typed property Test::$prop must not be accessed before initialization\n",
            "Init: 0, op: w: Cannot indirectly modify private(set) property Test::$prop from global scope\n",
            "Init: 0, op: rw: Typed property Test::$prop must not be accessed before initialization\n",
            "Init: 0, op: im: Cannot indirectly modify private(set) property Test::$prop from global scope\n",
            "Init: 0, op: is: 0\n",
            "Init: 0, op: us: done\n",
            "Init: 0, op: us_dim: done\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_object_read_property_for_nested_write_receiver"));
}

