#[test]
fn compile_reflection_new_instance_without_constructor_preserves_readonly_set_visibility_to_native_binary(
) {
    let root = temp_dir("ptn-native-reflection-readonly-set-visibility");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-readonly-set-visibility.php");
    let output = root.join("reflection-readonly-set-visibility-bin");
    fs::write(
        &input,
        "<?php
class P {
    public readonly int $pDefault;
    public private(set) readonly int $pPrivate;
    public protected(set) readonly int $pProtected;
}

class C extends P {
    public function writePrivate() {
        $this->pPrivate = 1;
    }
}

$c = (new ReflectionClass(C::class))->newInstanceWithoutConstructor();
try {
    $c->writePrivate();
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}

$p = (new ReflectionClass(P::class))->newInstanceWithoutConstructor();
try {
    $p->pDefault = 1;
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}

try {
    $p->pPrivate = 1;
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}

try {
    $p->pProtected = 1;
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "Cannot modify private(set) property P::$pPrivate from scope C\n",
            "Cannot modify protected(set) readonly property P::$pDefault from global scope\n",
            "Cannot modify private(set) property P::$pPrivate from global scope\n",
            "Cannot modify protected(set) readonly property P::$pProtected from global scope\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_declared_class_new_instance_without_constructor"));
    assert!(c_source.contains("newInstanceWithoutConstructor"));
}

#[test]
fn compile_non_public_property_static_compare_and_export_to_native_binary() {
    let root = temp_dir("ptn-native-non-public-property-static-compare");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("non-public-property-static-compare.php");
    let output = root.join("non-public-property-static-compare-bin");
    fs::write(
        &input,
        "<?php
class Secret {
    private $value;
    protected $token = \"seed\";
    public $label;

    public function __construct($value) {
        $this->value = $value;
        $this->label = \"box\";
    }

    public static function compare($left, $right) {
        return $left->value === $right->value;
    }

    public function update($value) {
        $this->token = $value;
        return $this->token;
    }
}

$a = new Secret(4);
$b = new Secret(4);
var_dump(Secret::compare($a, $b));
var_dump($a->update(\"changed\"));
var_dump($a);
echo var_export($a, true), \"\\n\";
try {
    var_dump($a->value);
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "string(7) \"changed\"\n",
            "object(Secret)#1 (3) {\n",
            "  [\"value\":\"Secret\":private]=>\n",
            "  int(4)\n",
            "  [\"token\":protected]=>\n",
            "  string(7) \"changed\"\n",
            "  [\"label\"]=>\n",
            "  string(3) \"box\"\n",
            "}\n",
            "\\Secret::__set_state(array(\n",
            "   'value' => 4,\n",
            "   'token' => 'changed',\n",
            "   'label' => 'box',\n",
            "))\n",
            "Cannot access private property Secret::$value\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_object_declare_property(&runtime"));
    assert!(c_source.contains("PTN_PROPERTY_PRIVATE"));
    assert!(c_source.contains("PTN_PROPERTY_PROTECTED"));
}

#[test]
fn compile_object_clone_magic_and_comparison_to_native_binary() {
    let root = temp_dir("ptn-native-object-clone-magic-comparison");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("object-clone-magic-comparison.php");
    let output = root.join("object-clone-magic-comparison-bin");
    fs::write(
        &input,
        "<?php
class Box {
    private $secret;
    public $label = \"box\";

    public function __construct($secret) {
        $this->secret = $secret;
    }

    public function __clone() {
        echo \"clone:\", $this->label, \"\\n\";
        $this->label = \"clone\";
    }

    public function expose() {
        return $this->label . \":\" . $this->secret;
    }
}

$a = new Box(7);
$b = clone $a;
var_dump($a == $b, $a === $b);
echo $a->expose(), \"\\n\";
echo $b->expose(), \"\\n\";
$c = clone clone $d = new stdClass;
var_dump($c == $d, $c === $d);
try {
    clone array();
} catch (TypeError $e) {
    echo \"TypeError: \", $e->getMessage(), \"\\n\";
}

class SortBox {
    public $class_value;

    public function __construct($class_value) {
        $this->class_value = $class_value;
    }
}

var_dump(new SortBox(1) <=> new SortBox(2));
var_dump(new SortBox(2) <=> new SortBox(1));
var_dump(new SortBox(1) <=> new SortBox(1));
$boxes = [new SortBox(2), new SortBox(-1), new SortBox(0)];
sort($boxes, SORT_REGULAR);
foreach ($boxes as $box) {
    echo $box->class_value, \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "clone:box\n",
            "bool(false)\n",
            "bool(false)\n",
            "box:7\n",
            "clone:7\n",
            "bool(true)\n",
            "bool(false)\n",
            "TypeError: clone(): Argument #1 ($object) must be of type object, array given\n",
            "int(-1)\n",
            "int(1)\n",
            "int(0)\n",
            "-1\n",
            "0\n",
            "2\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_clone_value(&runtime"));
    assert!(c_source.contains("root->method_dispatch(root, clone, \"__clone\""));
}

