#[test]
fn compile_magic_method_declaration_fatals_to_native_binary() {
    let cases = [
        (
            "magic-static-unset",
            "<?php
class Box {
    public static function __unset($name) {}
}
echo \"unreachable\\n\";
",
            "Method Box::__unset() cannot be static",
            3,
        ),
        (
            "magic-by-ref-call",
            "<?php
class Box {
    public function __call(&$name, $arguments) {}
}
echo \"unreachable\\n\";
",
            "Method Box::__call() cannot take arguments by reference",
            3,
        ),
        (
            "magic-call-name-type",
            "<?php
class Box {
    public static function __callStatic(int $name, array $arguments) {}
}
echo \"unreachable\\n\";
",
            "Box::__callStatic(): Parameter #1 ($name) must be of type string when declared",
            3,
        ),
        (
            "magic-call-arguments-type",
            "<?php
class Box {
    public function __call(string $name, Iterator $arguments) {}
}
echo \"unreachable\\n\";
",
            "Box::__call(): Parameter #2 ($arguments) must be of type array when declared",
            3,
        ),
    ];

    for (name, source, message, line) in cases {
        let root_name = format!("ptn-native-{name}");
        let root = temp_dir(&root_name);
        fs::create_dir_all(&root).unwrap();
        let input = root.join(format!("{name}.php"));
        let output = root.join(format!("{name}-bin"));
        fs::write(&input, source).unwrap();

        let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

        let execution = Command::new(&output).output().unwrap();
        assert!(!execution.status.success(), "{name}");
        assert_eq!(execution.status.code(), Some(255), "{name}");
        assert_eq!(String::from_utf8(execution.stdout).unwrap(), "", "{name}");
        assert_eq!(
            String::from_utf8(execution.stderr).unwrap(),
            format!(
                "Fatal error: {message} in {} on line {line}\n",
                input.display()
            ),
            "{name}"
        );

        let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
        assert!(c_source.contains(message), "{name}");
    }
}

#[test]
fn compile_non_public_method_visibility_dispatch_to_native_binary() {
    let root = temp_dir("ptn-native-non-public-method-visibility");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("non-public-method-visibility.php");
    let output = root.join("non-public-method-visibility-bin");
    fs::write(
        &input,
        "<?php
class Base {
    private function priv() { echo \"base-private\\n\"; }
    protected function prot() { echo \"base-protected\\n\"; }
    private static function statPriv() { echo \"base-static-private\\n\"; }
    protected static function statProt() { echo \"base-static-protected\\n\"; }

    public function inside() {
        $this->priv();
        $this->prot();
        self::statPriv();
        self::statProt();
        var_dump(is_callable([$this, 'priv']));
        var_dump(is_callable([self::class, 'statPriv']));
    }
}

class Child extends Base {
    public function insideChild() {
        $this->prot();
        self::statProt();
        var_dump(is_callable([$this, 'prot']));
        var_dump(is_callable([Base::class, 'statProt']));
        try { $this->priv(); } catch (Error $e) { echo $e->getMessage(), \"\\n\"; }
        try { Base::statPriv(); } catch (Error $e) { echo $e->getMessage(), \"\\n\"; }
    }
}

class Peer extends Base {
    protected static function statProt() { echo \"peer-static-protected\\n\"; }
}

class Sibling extends Base {
    public static function probePeer() {
        var_dump(is_callable('Peer::statProt'));
        Peer::statProt();
    }
}

class ParentAccess {
    public static function probeChild() {
        ChildAccess::prot();
        print_r(get_class_methods(\"ChildAccess\"));
    }
}

class ChildAccess extends ParentAccess {
    protected static function prot() { echo \"child-protected-static\\n\"; }
}

class Magic {
    private function hidden() { echo \"hidden\\n\"; }
    public function __call($name, $args) { echo \"magic:$name\\n\"; }
}

$child = new Child();
$child->inside();
$child->insideChild();
Sibling::probePeer();
ChildAccess::probeChild();
var_dump(method_exists($child, 'priv'));
var_dump(is_callable([$child, 'priv']));
var_dump(is_callable([Base::class, 'statProt']));
try { $child->prot(); } catch (Error $e) { echo $e->getMessage(), \"\\n\"; }
try { Base::statPriv(side_effect()); } catch (Error $e) { echo $e->getMessage(), \"\\n\"; }
(new Magic())->hidden();
function side_effect() { echo \"side-effect\\n\"; return 1; }
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "base-private\n",
            "base-protected\n",
            "base-static-private\n",
            "base-static-protected\n",
            "bool(true)\n",
            "bool(true)\n",
            "base-protected\n",
            "base-static-protected\n",
            "bool(true)\n",
            "bool(true)\n",
            "Call to private method Base::priv() from scope Child\n",
            "Call to private method Base::statPriv() from scope Child\n",
            "bool(true)\n",
            "peer-static-protected\n",
            "child-protected-static\n",
            "Array\n",
            "(\n",
            "    [0] => prot\n",
            "    [1] => probeChild\n",
            ")\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(false)\n",
            "Call to protected method Base::prot() from global scope\n",
            "Call to private method Base::statPriv() from global scope\n",
            "magic:hidden\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_declared_method_visibility_allows"));
    assert!(c_source.contains("ptn_throw_declared_method_visibility_error"));
}

