#[test]
fn compile_stream_writes_preserve_eof_indicator_to_native_binary() {
    let root = temp_dir("ptn-native-stream-write-eof");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("stream-write-eof.php");
    let output = root.join("stream-write-eof-bin");
    fs::write(
        &input,
        "<?php\n\
$path = __DIR__ . '/eof.txt';\n\
file_put_contents($path, 'abc');\n\
$file = fopen($path, 'ab+');\n\
fread($file, 99);\n\
var_dump(feof($file));\n\
var_dump(fwrite($file, 'x'));\n\
var_dump(feof($file));\n\
fread($file, 1);\n\
var_dump(feof($file));\n\
fclose($file);\n\
var_dump(file_get_contents($path));\n\
@unlink($path);\n\
\n\
$memory = fopen('php://memory', 'w+');\n\
fwrite($memory, 'abc');\n\
rewind($memory);\n\
fread($memory, 99);\n\
var_dump(feof($memory));\n\
var_dump(fwrite($memory, 'x'));\n\
var_dump(feof($memory));\n\
fseek($memory, 0);\n\
var_dump(feof($memory));\n\
var_dump(stream_get_contents($memory));\n",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "bool(true)\n\
int(1)\n\
bool(true)\n\
bool(true)\n\
string(4) \"abcx\"\n\
bool(true)\n\
int(1)\n\
bool(true)\n\
bool(false)\n\
string(4) \"abcx\"\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_namespaced_class_aliases_to_native_binary() {
    let root = temp_dir("ptn-native-namespace-class-aliases");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("namespace-class-aliases.php");
    let output = root.join("namespace-class-aliases-bin");
    fs::write(
        &input,
        r#"<?php
namespace test\ns1;

class Foo {
    function __construct() { echo __CLASS__, "\n"; }
    function bar() { echo __CLASS__, "\n"; }
    static function baz() { echo __CLASS__, "\n"; }
}

use test\ns1\Foo as Bar;
use test\ns1 as ns2;
use test\ns1;

$x = new Foo;
$x->bar();
Foo::baz();
$y = new \test\ns1\Foo;
$y->bar();
\test\ns1\Foo::baz();
Bar::baz();
ns2\Foo::baz();
ns1\Foo::baz();
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "test\\ns1\\Foo\n",
            "test\\ns1\\Foo\n",
            "test\\ns1\\Foo\n",
            "test\\ns1\\Foo\n",
            "test\\ns1\\Foo\n",
            "test\\ns1\\Foo\n",
            "test\\ns1\\Foo\n",
            "test\\ns1\\Foo\n",
            "test\\ns1\\Foo\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("test\\\\ns1\\\\Foo"));
}

