#[test]
fn parser_reports_break_compile_time_fatals() {
    let cases = [
        (
            "<?php function f() { break 0; }",
            "'break' operator accepts only positive integers",
        ),
        (
            "<?php function f() { break $x; }",
            "'break' operator with non-integer operand is no longer supported",
        ),
        (
            "<?php function f() { break; }",
            "'break' not in the 'loop' or 'switch' context",
        ),
        (
            "<?php function f() { while (1) { break 2; } }",
            "Cannot 'break' 2 levels",
        ),
    ];

    for (source, expected) in cases {
        let error = parser::parse(source).unwrap_err();
        assert_eq!(error.kind, DiagnosticKind::Fatal);
        assert_eq!(error.message, expected);
    }
}

#[test]
fn native_method_visibility_dispatch_and_is_callable_respect_scope() {
    let root = temp_dir("ptn-native-method-visibility-dispatch");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("method-visibility.php");
    let output = root.join("method-visibility-bin");
    fs::write(
        &input,
        r#"<?php
class Mom {
    protected function prot() { echo "protected method\n"; }
}
class Child extends Mom {
    public function callMom() { $this->prot(); }
}

class A {
    static protected function ma() { return "A::ma()"; }
    static private function mp() { return "A::mp()"; }
}
class B1 extends A {
    static protected function ma() { return "B1::ma()"; }
    static protected function mp() { return "B1::mp()"; }
}
class B2 extends A {
    static public function test() {
        echo A::ma(), "\n";
        try { echo A::mp(), "\n"; } catch (Throwable $e) { echo $e->getMessage(), "\n"; }
        echo B1::ma(), "\n";
        try { echo B1::mp(), "\n"; } catch (Throwable $e) { echo $e->getMessage(), "\n"; }
    }
}

class CallableBase {
    private function priv() {}
    protected function prot() {}
    static private function statPriv() {}
    static protected function statProt() {}
    public function ownScope() {
        var_dump(is_callable(array($this, 'priv')));
        var_dump(is_callable(array($this, 'prot')));
        var_dump(is_callable(array('CallableBase', 'statPriv')));
        var_dump(is_callable(array('CallableBase', 'statProt')));
    }
}
class CallableChild extends CallableBase {
    public function childScope() {
        var_dump(is_callable(array($this, 'priv')));
        var_dump(is_callable(array($this, 'prot')));
        var_dump(is_callable(array('CallableBase', 'statPriv')));
        var_dump(is_callable(array('CallableBase', 'statProt')));
    }
}

(new Child())->callMom();
B2::test();
$base = new CallableBase();
$base->ownScope();
var_dump(is_callable(array($base, 'priv')));
var_dump(is_callable(array($base, 'prot')));
$child = new CallableChild();
$child->childScope();
?>"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "protected method\n",
            "A::ma()\n",
            "Call to private method A::mp() from scope B2\n",
            "B1::ma()\n",
            "Call to protected method B1::mp() from scope B2\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(false)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn native_method_visibility_uncaught_trace_uses_instance_frames() {
    let root = temp_dir("ptn-native-method-visibility-uncaught-trace");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("method-visibility-uncaught-trace.php");
    let output = root.join("method-visibility-uncaught-trace-bin");
    fs::write(
        &input,
        r#"<?php
class D {
    private function test2() {
        print "unreached\n";
    }
}
abstract class A extends D {
    public function test() {
        $this->test2();
    }
}
abstract class B extends A {
}
class C extends B {
    public function __construct() {
        $this->test();
    }
}
new C;
?>"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(!execution.status.success());
    assert_eq!(String::from_utf8(execution.stdout).unwrap(), "");
    assert_eq!(
        String::from_utf8(execution.stderr).unwrap(),
        format!(
            "\nFatal error: Uncaught Error: Call to private method D::test2() from scope A in {}:9\nStack trace:\n#0 {}(16): A->test()\n#1 {}(19): C->__construct()\n#2 {{main}}\n  thrown in {} on line 9\n",
            input.display(),
            input.display(),
            input.display(),
            input.display()
        )
    );
}

#[test]
fn compile_reference_reflection_and_http_query_edges_to_native_binary() {
    let root = temp_dir("ptn-native-reference-reflection-http-query");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reference-reflection-http-query.php");
    let output = root.join("reference-reflection-http-query-bin");
    fs::write(
        &input,
        r#"<?php
class TestClass {
    public function &foo() {
        static $value = 1;
        return $value;
    }
    private function bar() {}
}

$methodInfo = ReflectionMethod::createFromMethodName('TestClass::foo');
var_dump($methodInfo->returnsReference());
$methodInfo = ReflectionMethod::createFromMethodName('TestClass::bar');
var_dump($methodInfo->returnsReference());

$ary = [0, 1, 2];
$ref1 =& $ary[1];
unset($ref1);
$ref2 =& $ary[2];
$r1 = ReflectionReference::fromArrayElement($ary, 1);
var_dump($r1 === null);
$r2 = ReflectionReference::fromArrayElement($ary, 2);
var_dump($r2 instanceof ReflectionReference);
var_dump($r2->getId() === $r2->getId());
$self = [&$self];
$copy = [$self];
unset($self);
var_dump(ReflectionReference::fromArrayElement($copy[0], 0) instanceof ReflectionReference);
try {
    serialize($r2);
} catch (Exception $e) {
    echo $e->getMessage(), "\n";
}
try {
    unserialize('O:19:"ReflectionReference":0:{}');
} catch (Exception $e) {
    echo $e->getMessage(), "\n";
}

$value = 'value';
$ref =& $value;
var_dump(http_build_query([$ref]));
echo http_build_query(["name" => "main page"], "", ini_get("arg_separator.output"), PHP_QUERY_RFC3986), "\n";
?>"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "Serialization of 'ReflectionReference' is not allowed\n",
            "Unserialization of 'ReflectionReference' is not allowed\n",
            "string(7) \"0=value\"\n",
            "name=main%20page\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

fn temp_dir(name: &str) -> std::path::PathBuf {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    std::env::temp_dir().join(format!("{name}-{}-{now}", std::process::id()))
}

fn phpc_bin() -> PathBuf {
    option_env!("CARGO_BIN_EXE_phpc")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("target/debug/phpc"))
}
